(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.012-t*0.18)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.016-t*0.22)*18+Math.sin(x*0.014+t*0.3)*12+Math.cos((x-y)*0.009-t*0.12)*8;
  const w2x = Math.sin(w1x*0.02+t*0.15)*10+Math.cos(w1y*0.015-t*0.1)*7;
  const w2y = Math.cos(w1y*0.02-t*0.12)*10+Math.sin(w1x*0.018+t*0.2)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.45+2)*50,0.11,2.1,1.0],
    [400+Math.cos(t*0.55+1)*80,200+Math.sin(t*0.65+4)*60,0.055,2.4,1.1],
    [200+Math.sin(t*0.42+6)*110,220+Math.cos(t*0.38+3)*70,0.095,1.8,0.9]
  ];
  let aS=0,iS=0,cross=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    cross+=Math.sin(d*f*1.3-t*sp*0.8+2.0)*amp*0.5;
  }
  const act=aS/9,inh=iS/9,crs=cross/9;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.07+t*0.5)*Math.sin(sy*0.09-t*0.7)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2=Math.sin(dist*0.08-ang*5+t*0.9)*0.15+Math.sin(dist*0.03+ang*2-t*2.1)*0.15;
  const spiral=sp1+sp2;
  const diff=Math.sin(act*1.5+inh*0.8+crs*0.5)*0.4;
  const feed=Math.sin(act-inh*0.5+spiral*0.3)*0.3;
  const kill=Math.cos(inh*1.2-act*0.4+bg*0.2)*0.3;
  const cell1=Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const cell2=Math.sin(sx*0.22+t*0.3)*Math.sin(sy*0.18-t*0.4);
  const cell=(cell1+cell2*0.5+Math.sin((sx+sy)*0.1+t)*0.4)/1.9;
  const rawR=act-inh*0.6+bg*0.25+spiral+diff+feed*0.4-kill*0.3+crs*0.3;
  const reaction=Math.tanh(rawR*1.8);
  const cellVal=Math.tanh(cell*1.5)*0.25;
  const absR=Math.abs(reaction);
  const glow=absR>0.6?Math.pow((absR-0.6)/0.4,1.5)*0.3:0;
  const blend=reaction*0.65+cellVal*0.2+glow;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,95],[18,85,120],[25,135,135],[45,165,120],[120,185,85],[210,195,60],[235,155,55],[225,105,65],[185,60,70],[120,35,65],[65,18,55],[20,12,48],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=absR>0.72?1.12+glow*0.15:0.95+glow*0.1;
  const fl=lum*edge;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl)|0
  ];
}
